    /// Both speech models (paths are relative to Paths.models).
    static var speechModels: [RemoteFile] { speechHinglish + speechEnglish }
    static var speechModelBytes: Int64 { speechModels.reduce(0) { $0 + $1.size } }

    static func llmFiles(_ model: LLMModelInfo) -> [RemoteFile] {
        [RemoteFile(url: model.url, path: model.file, size: Int64(model.sizeMB) * 1_000_000, sha256: model.sha256)]
    }
